#!/bin/bash
#SBATCH --job-name=eqsans_ml_%j
#SBATCH --error=eqsans_ml_%j.err
#SBATCH --output=eqsans_ml_%j.out
#SBATCH --nodes 1
#SBATCH --partition=mesonet
#SBATCH --gres=gpu:1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=112
#SBATCH --time 03:00:00
#SBATCH --account m26216
set -euo pipefail

export MAMBA_EXE='/projects/m26216/INSTALL/bin/micromamba'
export MAMBA_ROOT_PREFIX='/projects/m26216/INSTALL/micromamba/'
eval "$("$MAMBA_EXE" shell hook --shell bash --root-prefix "$MAMBA_ROOT_PREFIX" 2> /dev/null)"
micromamba activate panraid

# Absolute path captured when THIS FILE WAS GENERATED (by make_run_script.py,
# run interactively, not inside a batch job -- so os.getcwd() there is
# unambiguous). Do not rely on SLURM's default working directory: it varies
# by cluster config, and guessing it wrong is exactly what broke the two
# earlier versions of this script.
cd /Users/georgeyumnam/WORK/PANRAID/FINAL_RESULTS/Group2

# Compile once; every run below calls the binary directly (same pattern as
# run_generated_sphere.sh). Using --format=McStas: this project's own local
# build did not have NeXus support compiled in despite libnexus being
# installed (see ML_PROBLEM_DEFINITION notes) -- if Juliet's mcstas build
# does support NeXus, change both this line and every run line below.
mkdir -p dataset_smoke
mcrun -c -n0 --format=McStas eqsans_cylinder.instr

# 1000 runs, 112 at a time (batches of --jobs, each
# backgrounded then waited on -- every line is still a plain,
# individually-runnable command, just not run one-at-a-time).

